async teardownSession(sessionId) {
    const session = this.sessions[sessionId];
    if (!session) {
        return;
    }
    if (session.closePromise) {
        await session.closePromise;
        return;
    }
    session.closePromise = (async () => {
        const consumer = session.consumer;
        if (session.activeTurn || session.turnQueue?.length) {
            await this.cancel({ sessionId });
        }
        // Wake the captured consumer without destroying its query resources.
        // runConsumer observes `closing`, swallows the abandoned next() rejection,
        // and terminates before this continuation releases the stream.
        disarmForceCancel(session);
        session.closing = true;
        session.cancelController?.abort();
        if (consumer) {
            await consumer;
        }
        this.closeQueryStream(session);
        session.abortController.abort();
        delete this.sessions[sessionId];
    })();
    await session.closePromise;
}
